package shape

import (
	"os"
	"path/filepath"
	"testing"
)

const recheckHashSlug = "hash-fixture"

// recheckHashFixture writes a valid project with one draft and returns its root.
func recheckHashFixture(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	recheckHashWrite(t, root, ".kogen/project.yaml", "version: 1\ncommands:\n  checks:\n    - name: compile\n      run: 'true'\n")
	recheckHashWrite(t, root, ".kogen/intents/"+recheckHashSlug+"/intent.md", "# Fixture\n\nSlug: "+recheckHashSlug+"\n")
	recheckHashWrite(t, root, ".kogen/intents/"+recheckHashSlug+"/acceptance.feature", "Feature: fixture\n")
	return root
}

func recheckHashWrite(t *testing.T, root, rel, body string) {
	t.Helper()
	p := filepath.Join(root, filepath.FromSlash(rel))
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
}

func TestRecheckDraftHashIsStableAndNonempty(t *testing.T) {
	root := recheckHashFixture(t)
	first, err := RecheckDraftHash(root, recheckHashSlug)
	if err != nil {
		t.Fatal(err)
	}
	second, err := RecheckDraftHash(root, recheckHashSlug)
	if err != nil {
		t.Fatal(err)
	}
	if first == "" {
		t.Fatal("RecheckDraftHash returned an empty hash")
	}
	if first != second {
		t.Fatalf("RecheckDraftHash is not stable: %q then %q", first, second)
	}
}

func TestRecheckDraftHashChangesWithDraftFile(t *testing.T) {
	root := recheckHashFixture(t)
	before, err := RecheckDraftHash(root, recheckHashSlug)
	if err != nil {
		t.Fatal(err)
	}
	recheckHashWrite(t, root, ".kogen/intents/"+recheckHashSlug+"/acceptance.feature", "Feature: changed\n")
	after, err := RecheckDraftHash(root, recheckHashSlug)
	if err != nil {
		t.Fatal(err)
	}
	if after == "" || after == before {
		t.Fatalf("hash did not change with the draft file: %q then %q", before, after)
	}
}

func TestRecheckDraftHashErrorsWithoutValidProject(t *testing.T) {
	missing := t.TempDir()
	if hash, err := RecheckDraftHash(missing, recheckHashSlug); err == nil || hash != "" {
		t.Fatalf("a root without a project configuration returned %q, %v; want an error", hash, err)
	}
	invalid := recheckHashFixture(t)
	recheckHashWrite(t, invalid, ".kogen/project.yaml", "version: 1\ncommands: [\n")
	if hash, err := RecheckDraftHash(invalid, recheckHashSlug); err == nil || hash != "" {
		t.Fatalf("an invalid project configuration returned %q, %v; want an error", hash, err)
	}
}

